files.guard.yaml:
version: 1
metrics:
  source: [src]
  profiles:
    standard:
      limits:
        file: {lines: 1, ncloc: 1}
        class: {lines: 1}
        method: {lines: 1, cyclomatic_complexity: 1}
  default: standard
structure:
  paths: [src]
  directories:
    - {path: 'src', allow: ['*.php'], require: [Required.php], max_files: 1}
documentation:
  files:
    README.md: {headings: ['# Expected', '## Details']}
    MISSING.md: {headings: ['# Missing']}
  scan: ['**/*.md']
configuration:
  - {id: count, file: app.json, select: /count, assert: {min: 1}, repair: 2}
  - {id: mode, file: app.json, select: /mode, level: recommended, assert: {equals: new}}

version: 1
configuration:
  - {id: value, file: app.json, format: json, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: value, file: app.json5, format: json5, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: value, file: app.yaml, format: yaml, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: value, file: app.neon, format: neon, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: value, file: app.toml, format: toml, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: value, file: app.xml, format: xml, select: /app/@value, assert: {equals: '1'}}

version: 1
configuration:
  - {id: value, file: settings.php, format: php, select: /return/value, assert: {equals: 1}}

version: 1
configuration:
  - {id: first, file: a.json, select: /value, assert: {equals: 1}}
  - {id: second, file: b.json, select: /value, assert: {equals: 1}}
  - {id: conflict, file: b.json, select: /value, assert: {equals: 2}}

version: 1
configuration:
  - {id: value, file: app.json, select: /value, level: recommended, assert: {min: 1}}

version: 1
configuration:
  - {id: first, file: a.json, select: /value, assert: {equals: 1}}
  - {id: broken, file: b.json, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: first, file: app.json, format: json, select: /value, assert: {equals: 1}}
  - {id: second, file: app.json, format: yaml, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: self, file: guard.yaml, select: /version, assert: {equals: 1}}

version: 1
structure:
  paths: [src]
  directories:
    - {path: '**', allow: ['*.php'], max_depth: 1}
    - {path: 'src/**', require: [index.php], file_case: pascal}

files.loc.yaml:
scan: {roots: [src], exclude: []}
policies: {standard: {limits: {file: {lines: 10}}}}
apply: {default: standard, rules: []}

files.guard.yaml:
version: 1
configuration:
  - {id: bad-selector, file: a.json, select: missing-slash, assert: {equals: 1}}
  - {id: bad-json, file: b.json, select: /mode, assert: {equals: 1}}

version: 1
configuration:
  - {id: value, file: app.yaml, select: /value, assert: {equals: 1}}

version: 1
configuration:
  - {id: risky, file: fixer.php, format: php, select: /riskyAllowed, assert: {equals: true}}
  - {id: strict, file: fixer.php, format: php, select: /rules/strict_comparison, assert: {equals: true}}

version: 1
configuration:
  - {id: alias, file: app.yaml, select: /first/value, assert: {equals: 1}}
